#include "core_api.h"

#include <algorithm>
#include <cstdio>
#include <string>
#include <vector>

#include "preset/factory.h"

// The factory-preset half of the C API. It lives apart from core_api.cpp because the factory table
// is generated by the preset tool, which itself uses makeCoreApi: core_api.cpp cannot depend on it.
namespace eg13 {

namespace {

CoreApiContext& ctx(void* context) { return *static_cast<CoreApiContext*>(context); }

// This plugin kind's factory presets in list order: bank (Bank 1, Bank 2, FX, any other last), then order.
std::vector<const preset::FactoryPreset*> factoryList(PluginKind kind) {
  size_t count = 0;
  const preset::FactoryPreset* table = preset::factoryPresets(count);
  std::vector<const preset::FactoryPreset*> list;
  for (size_t i = 0; i < count; ++i) {
    if (table[i].plugin == kind) list.push_back(&table[i]);
  }
  const auto rank = [](const preset::FactoryPreset* p) {
    const std::string bank = p->bank ? p->bank : "";
    return bank == "Bank 1" ? 0 : bank == "Bank 2" ? 1 : bank == "FX" ? 2 : 3;
  };
  std::stable_sort(list.begin(), list.end(), [&](const auto* a, const auto* b) {
    return rank(a) != rank(b) ? rank(a) < rank(b) : a->order < b->order;
  });
  return list;
}

uint32_t factoryPresetCount(void* context) noexcept {
  try {
    return uint32_t(factoryList(ctx(context).synth.kind()).size());
  } catch (...) {
    return 0;
  }
}

bool factoryPreset(void* context, uint32_t index, EG13FactoryPreset* out) noexcept {
  if (!out) return false;
  try {
    const auto list = factoryList(ctx(context).synth.kind());
    if (index >= list.size()) return false;
    const preset::FactoryPreset& p = *list[index];
    out->bank = p.bank;
    out->name = p.name;
    out->note = p.note;
    out->credit = p.credit;
    out->licence = p.licence;
    out->kind = p.kind == preset::Kind::Patch ? 1u : 0u;
    out->json = p.json;
    return true;
  } catch (...) {
    return false;
  }
}

}  // namespace

void attachFactoryPresets(EG13CoreAPI& api) {
  api.factory_preset_count = factoryPresetCount;
  api.factory_preset = factoryPreset;
}

// A JSON string literal for text (names are free text).
static std::string jsonQuote(const std::string& text) {
  std::string out = "\"";
  for (const char c : text) {
    if (c == '"' || c == '\\') {
      out += '\\';
      out += c;
    } else if (static_cast<unsigned char>(c) < 0x20) {
      char buf[8];
      std::snprintf(buf, sizeof buf, "\\u%04x", unsigned(static_cast<unsigned char>(c)));
      out += buf;
    } else {
      out += c;
    }
  }
  return out + "\"";
}

bool applyFirstLoadPreset(PluginKind kind, const std::function<std::string()>& save,
                          const std::function<int(const std::string&)>& load,
                          const std::function<void(const std::string&)>& setBrowser) {
  if (kind != PluginKind::Instrument) return false;
  try {
    size_t count = 0;
    const preset::FactoryPreset* table = preset::factoryPresets(count);
    for (size_t i = 0; i < count; ++i) {
      if (table[i].plugin != kind || !table[i].firstLoad) continue;
      std::string message;
      const int32_t result = applyPresetJson(kind, save, load, table[i].json, -1, message);
      if (result == EG13_PRESET_INVALID) return false;
      // The editor's browser string (its format is the UI's, EG13PresetBrowser.swift): the header
      // name strip shows this preset's name from the first open.
      if (setBrowser) {
        setBrowser("{\"version\":2,\"loaded\":[{\"part\":-1,\"bank\":" + jsonQuote(table[i].bank ? table[i].bank : "") +
                   ",\"name\":" + jsonQuote(table[i].name ? table[i].name : "") +
                   ",\"kind\":\"performance\"}],\"edited\":[false,false]}");
      }
      return true;
    }
  } catch (...) {
  }
  return false;
}

}  // namespace eg13
